param([string]$PythonExe="",[string]$RepoRoot="D:\AssertionForge-main1",[string]$RelayUrl="https://api.highwayapi.ai/openai/chat/completions",[int]$Seed=20260722)
$ErrorActionPreference="Stop"; if(-not $PythonExe){$p=Join-Path $env:USERPROFILE ".cache\codex-runtimes\codex-primary-runtime\dependencies\python\python.exe";if(Test-Path $p){$PythonExe=$p}else{$PythonExe=(Get-Command python -ErrorAction Stop).Source}}; Set-Location -LiteralPath $RepoRoot
$out="outputs/candidate_count_cost_v2_actual"; if(Test-Path "$out/candidate_count_freeze.json"){throw "$out is already frozen; do not overwrite it."}
$names=@("OPENAI_API_KEY","ANTHROPIC_API_KEY","MULTIMODEL_OPENAI_BASE_URL","MULTIMODEL_OPENAI_MODEL","MULTIMODEL_OPENAI_MAX_RETRIES","MULTIMODEL_OPENAI_RETRY_BACKOFF_SEC","MULTIMODEL_CLAUDE_PROVIDER","MULTIMODEL_CLAUDE_BASE_URL","MULTIMODEL_CLAUDE_MODEL","MULTIMODEL_CLAUDE_MAX_RETRIES","MULTIMODEL_CLAUDE_RETRY_BACKOFF_SEC","MULTIMODEL_SEED","PYTHONHASHSEED");$old=@{};foreach($n in $names){$old[$n]=[Environment]::GetEnvironmentVariable($n,"Process")};$secure=Read-Host "Highway API key" -AsSecureString;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
try{$key=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr);$env:OPENAI_API_KEY=$key;$env:ANTHROPIC_API_KEY=$key;$env:MULTIMODEL_OPENAI_BASE_URL=$RelayUrl;$env:MULTIMODEL_OPENAI_MODEL="gpt-5.4";$env:MULTIMODEL_OPENAI_MAX_RETRIES="8";$env:MULTIMODEL_OPENAI_RETRY_BACKOFF_SEC="5";$env:MULTIMODEL_CLAUDE_PROVIDER="openai_compatible";$env:MULTIMODEL_CLAUDE_BASE_URL=$RelayUrl;$env:MULTIMODEL_CLAUDE_MODEL="claude-opus-4-8";$env:MULTIMODEL_CLAUDE_MAX_RETRIES="8";$env:MULTIMODEL_CLAUDE_RETRY_BACKOFF_SEC="5";$env:MULTIMODEL_SEED="$Seed";$env:PYTHONHASHSEED="$Seed"
& $PythonExe src/run_trace_representation_ablation.py --root rtl_cases_real_scale120 --output-dir $out --temporal-summary-json outputs/formal_temporal_abstractions/temporal_abstractions.json --all-cases --model GPT --model Claude --method spec_rtl_raw_trace --method spec_rtl_temporal_relation_abstraction --candidates-per-cell 4 --resume
if($LASTEXITCODE-ne 0){throw "Fresh candidate generation/validation failed"}; & $PythonExe src/build_candidate_count_actual_cost.py --run-dir $out; if($LASTEXITCODE-ne 0){throw "Actual-cost report failed"}}
finally{if($ptr-ne[IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr)};$key=$null;foreach($n in $names){[Environment]::SetEnvironmentVariable($n,$old[$n],"Process")}}
